% interface to terminal command line% gets the input as JSON coded data/structure and...% split targeted Octave calling function and...% if input argument is provided or...% if resulted output is requested, would be sent back to terminal% never use disp function in your code (adds newline)function fBridge()  myJson = '';% empty myStr/myJson  %% get and combine strings into one  while true    %% get the input myStr from terminal (as a apart of input JSON)    myStr = fgets(stdin);    if myStr == -1      % nothing to add      break;% exit    else      myJson = [myJson,myStr];% append    endif  endwhile  %% Json is collected as string from input cmd  myData = jsondecode(myJson);% converted back to struct()  clear myJson myStr  %% go by mySelf (inputs allready taken)  %1-get the name of targeted function  funcName = myData.name;% always string  %2-find the input argumans  if isfield(myData,"args")    funcArgs = myData.args;% cell of anything  end%if  if isfield(myData,"ret")    % call and send back the outputs    if isfield(myData,"args")      yourData = feval(funcName,funcArgs{:});#1 output & input    else% no input is provided      yourData = feval(funcName);#2 output only    endif    yourJson = jsonencode(yourData);    printf("%s", yourJson);  else % just RUN, no output is requested    if isfield(myData,"args")      feval(funcName,funcArgs{:});#3 input only    else      % no input is provided      feval(funcName);#4 neither input nor output    endif  endifendfunction